const aiCategoryLabel=$('aiCategory').closest('label');const aiContentTypeLabel=document.createElement('label');aiContentTypeLabel.innerHTML='<span>콘텐츠 유형</span><select id="aiContentType"><option value="guide">등기가이드</option><option value="workbook">실무워크북</option><option value="insight">인사이트</option></select>';aiCategoryLabel.before(aiContentTypeLabel);
const views={dashboard:$('automationDashboard'),settings:$('automationSettings'),naver:$('naverPostsView')};const navs={dashboard:$('navDashboard'),settings:$('navSettings'),contents:$('navContents'),trash:$('trashButton'),naver:$('navNaver')};
const projectSelect=$('projectSelect');const projectSwitcher=projectSelect.closest('.project-switcher');const projectNavigation=$('projectNavigation');const homeqContentNavigation=$('homeqContentNavigation');const workspaceHome=$('workspaceHomeView');const homeqWorkspace=$('homeqWorkspace');const contentTypeWorkspace=$('contentTypeWorkspace');const qratorContentsAction=navs.contents.onclick;const qratorTrashAction=navs.trash.onclick;let activeProject=localStorage.getItem('content-studio:project')==='homeq'?'homeq':'qrator';let activeSection='contents';let activeContentType='all';
function canLeaveEditor(){if($('editorView').hidden)return true;const label=$('saveState').textContent;return !/변경|임시 저장/.test(label)||confirm('저장하지 않은 변경사항이 있습니다. 다른 화면으로 이동하시겠습니까?');}
function activateNav(name){document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));navs[name]?.classList.add('active');}
function activateContentType(type){document.querySelectorAll('#qratorContentTabs [data-content-type]').forEach(x=>{const active=x.dataset.contentType===type;x.classList.toggle('active',active);x.setAttribute('aria-selected',String(active));});}
function activateHomeqSection(section){document.querySelectorAll('[data-homeq-section]').forEach(x=>x.classList.toggle('active',x.dataset.homeqSection===section));}
function hideProjectViews(){[$('listView'),$('editorView'),workspaceHome,homeqWorkspace,contentTypeWorkspace,...Object.values(views)].forEach(v=>v.hidden=true);}
function showProjectNavigation(){navs.naver.hidden=activeProject!=='qrator';projectSwitcher.hidden=false;projectNavigation.hidden=false;projectSelect.value=activeProject;homeqContentNavigation.hidden=activeProject!=='homeq';$('navWorkspaceHome').classList.remove('active');}
function updateQratorListHeading(){$('contentListTitle').textContent='콘텐츠 목록';$('contentListDescription').textContent='홈페이지 콘텐츠의 작성과 게시 상태를 관리합니다.';}
function showWorkspaceHome(skipGuard=false){if(!skipGuard&&!canLeaveEditor())return;hideProjectViews();workspaceHome.hidden=false;projectSwitcher.hidden=true;projectNavigation.hidden=true;$('navWorkspaceHome').classList.add('active');const count=document.querySelector('#totalCount')?.textContent.match(/총\s+(\d+)건/)?.[1];if(count)$('workspaceQratorCount').textContent=count+'건';window.scrollTo({top:0,behavior:'instant'});}
function showAutomation(name,skipGuard=false){if(!skipGuard&&!canLeaveEditor())return;showProjectNavigation();activeSection=name;hideProjectViews();views[name].hidden=false;activateNav(name);if(name==='dashboard'){refreshAiDashboard();refreshDashboardInsights();}if(name==='naver')loadNaverPosts();window.scrollTo({top:0,behavior:'instant'});}
function showQratorType(type='all',skipGuard=false){if(!skipGuard&&!canLeaveEditor())return;if(!['all','guide','workbook','insight'].includes(type))type='all';activeContentType=type;activeSection='contents';showProjectNavigation();hideProjectViews();activateNav('contents');activateContentType(type);updateQratorListHeading();$('listView').hidden=false;document.dispatchEvent(new CustomEvent('qrator:content-type',{detail:type}));window.scrollTo({top:0,behavior:'instant'});}
const homeqCopy={weekly:['부동산 주간뉴스','매주 3개 부동산 이슈를 카드뉴스와 인스타 캡션으로 제작합니다.'],features:['홈큐 기능 연계 카드뉴스','HomeQ 기능과 연결되는 주 2회 마케팅 카드뉴스를 준비하는 공간입니다.','기능 연계 카드뉴스','주간뉴스 자동화가 안정화된 뒤 두 번째 콘텐츠 유형으로 연결합니다.'],dashboard:['HomeQ 콘텐츠 대시보드','카드뉴스와 블로그의 제작·검토·발행 현황을 확인하는 공간입니다.','HomeQ 대시보드','채널별 제작 현황과 오늘 처리할 작업을 이곳에 연결합니다.'],contents:['HomeQ 전체 콘텐츠','인스타 카드뉴스와 블로그 콘텐츠를 함께 관리하는 공간입니다.','전체 콘텐츠','HomeQ의 채널별 콘텐츠 목록을 이곳에 연결합니다.'],cards:['인스타 카드뉴스','카드뉴스 유형별 제작 흐름을 관리합니다.'],blog:['HomeQ 블로그','부동산 뉴스와 서비스 마케팅 원고를 관리합니다.','블로그 작업 공간','블로그 템플릿과 초안·검토·발행 상태를 이곳에 연결합니다.'],assets:['이미지·자료','카드뉴스와 블로그에서 사용하는 이미지와 출처를 관리합니다.','이미지·자료 보관함','생성 이미지·원본·출처 정보를 한곳에서 관리할 예정입니다.'],settings:['HomeQ 생성 설정','부동산 주간뉴스의 일정·템플릿·작성·이미지 규칙을 관리합니다.'],trash:['HomeQ 휴지통','삭제한 HomeQ 콘텐츠와 이미지 작업을 관리하는 공간입니다.','휴지통','HomeQ에서 삭제한 작업만 별도로 표시합니다.']};
let homeqSettingsRevision=null;let homeqSettingsLoaded=false;
function showHomeq(name=activeSection,skipGuard=false){if(!skipGuard&&!canLeaveEditor())return;showProjectNavigation();if(name==='cards')name='weekly';activeSection=name;hideProjectViews();const copy=homeqCopy[name]||homeqCopy.weekly;$('homeqPageTitle').textContent=copy[0];$('homeqPageDescription').textContent=copy[1];homeqWorkspace.hidden=false;$('homeqWeeklyView').hidden=name!=='weekly';$('homeqSettingsView').hidden=name!=='settings';$('homeqPlaceholderView').hidden=['weekly','settings'].includes(name);$('homeqCreateWeekly').hidden=name!=='weekly';if($('homeqPlaceholderView').hidden===false){$('homeqPlaceholderTitle').textContent=copy[2]||copy[0];$('homeqPlaceholderCopy').textContent=copy[3]||copy[1];}activateNav(['weekly','features','blog','assets','contents'].includes(name)?'contents':name);activateHomeqSection(name);if(name==='settings')loadHomeqSettings();if(name==='weekly')loadHomeqDraft();window.scrollTo({top:0,behavior:'instant'});}
function openProject(project){if(!canLeaveEditor())return;activeProject=project;localStorage.setItem('content-studio:project',project);showProjectNavigation();if(project==='homeq')showHomeq('weekly',true);else{activeContentType='all';showQratorType('all',true);}}
function switchProject(project){if(!canLeaveEditor()){projectSelect.value=activeProject;return;}openProject(project);}
let settingsRevision=null;let settingsLoaded=false;
async function automationApi(op,options={}){const params=new URLSearchParams({op,...(options.query||{})});const response=await fetch('/api/studio?'+params,{method:options.method||'GET',headers:options.body?{'Content-Type':'application/json'}:undefined,body:options.body?JSON.stringify(options.body):undefined});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'설정을 불러오지 못했습니다.');return data;}
async function loadAutomationSettings(){if(settingsLoaded)return;try{const data=await automationApi('getSettings');if(data.settings){$('automationWritingRules').value=data.settings.writingRules;$('writingRuleVersion').textContent='작성 지침 · '+(data.settings.ruleVersion||'저장됨');settingsRevision=data.settings.revision;}settingsLoaded=true;}catch(e){toast(e.message);}}
async function loadHomeqSettings(){if(homeqSettingsLoaded)return;try{const data=await automationApi('getHomeqSettings');if(data.settings){$('homeqWeekday').value=data.settings.weekday;$('homeqTime').value=data.settings.time;$('homeqTopicCount').value=data.settings.topicCount;$('homeqWritingRules').value=data.settings.writingRules;$('homeqRuleVersion').textContent='주간뉴스 지침 · '+data.settings.ruleVersion;homeqSettingsRevision=data.settings.revision;updateHomeqSchedule();}homeqSettingsLoaded=true;}catch(e){toast(e.message);}}
function updateHomeqSchedule(){const day=$('homeqWeekday').value;const time=$('homeqTime').value;$('homeqScheduleSummary').textContent=`매주 ${day}요일 · ${time}`;$('homeqNextRun').textContent=`${day}요일 ${time}`;}
navs.dashboard.onclick=()=>activeProject==='homeq'?showHomeq('dashboard'):showAutomation('dashboard');navs.settings.onclick=()=>{if(activeProject==='homeq'){showHomeq('settings');return;}showAutomation('settings');loadAutomationSettings();};navs.naver.onclick=()=>showAutomation('naver');navs.contents.onclick=()=>{if(activeProject==='homeq'){showHomeq('weekly');return;}activeContentType='all';qratorContentsAction?.call(navs.contents);showQratorType('all',true);};navs.trash.onclick=()=>activeProject==='homeq'?showHomeq('trash'):qratorTrashAction?.call(navs.trash);$('navWorkspaceHome').onclick=()=>showWorkspaceHome();projectSelect.value=activeProject;projectSelect.onchange=()=>switchProject(projectSelect.value);document.querySelectorAll('[data-open-project]').forEach(x=>x.onclick=()=>openProject(x.dataset.openProject));document.querySelectorAll('#qratorContentTabs [data-content-type]').forEach(x=>x.onclick=()=>showQratorType(x.dataset.contentType));document.querySelectorAll('[data-homeq-section]').forEach(x=>x.onclick=()=>showHomeq(x.dataset.homeqSection));document.addEventListener('content-studio:ready',()=>showWorkspaceHome(true));document.addEventListener('qrator:view',e=>{if(e.detail==='contents'&&activeProject==='qrator'){workspaceHome.hidden=true;Object.values(views).forEach(v=>v.hidden=true);homeqWorkspace.hidden=true;contentTypeWorkspace.hidden=true;activeSection='contents';showProjectNavigation();activateNav('contents');activateContentType(activeContentType);updateQratorListHeading();document.dispatchEvent(new CustomEvent('qrator:content-type',{detail:activeContentType}));}});showWorkspaceHome(true);
function toast(message){let el=$('automationToast');if(!el){el=document.createElement('div');el.id='automationToast';document.body.append(el);}el.textContent=message;el.hidden=false;clearTimeout(el.timer);el.timer=setTimeout(()=>el.hidden=true,2800);}
function openDialog(dialog){if(!dialog.open)dialog.showModal();}
