function parseAiGrid(raw){
 const source=String(raw||'').trim();if(!source)return [];
 const firstLine=source.split(/\r?\n/,1)[0]||'',delimiter=firstLine.includes('\t')?'\t':',';
 const rows=[];let row=[],cell='',quoted=false;
 for(let index=0;index<source.length;index++){
  const char=source[index];
  if(char==='"'){if(quoted&&source[index+1]==='"'){cell+='"';index++;}else quoted=!quoted;continue;}
  if(!quoted&&char===delimiter){row.push(cell.trim());cell='';continue;}
  if(!quoted&&(char==='\n'||char==='\r')){if(char==='\r'&&source[index+1]==='\n')index++;row.push(cell.trim());cell='';if(row.some(value=>value))rows.push(row);row=[];continue;}
  cell+=char;
 }
 row.push(cell.trim());if(row.some(value=>value))rows.push(row);return rows;
}
const aiHeaderKey=value=>String(value||'').toLowerCase().replace(/[\s·/_-]+/g,'');
const AI_SCHEDULE_HEADERS={sequence:['순번'],month:['월'],progress:['진행상황','상태'],assignee:['담당'],publishDate:['발행일'],weekday:['요일'],series:['시리즈'],keywords:['키워드'],brief:['소재기획방향','소재','기획방향'],blogUrl:['블로그url'],references:['참고자료'],topic:['주제'],category:['카테고리']};
function aiHeaderMap(row){const map={};row.forEach((value,index)=>{const key=aiHeaderKey(value);for(const [name,aliases] of Object.entries(AI_SCHEDULE_HEADERS))if(aliases.includes(key)){map[name]=index;break;}});return map;}
function inferAiCategory(text){const value=String(text||'');const matches=[['상호',/상호|회사명/],['본점',/본점|주소\s*이전/],['목적',/사업\s*목적|목적\s*변경/],['임원',/임원|대표이사|이사|감사|중임|퇴임|사임/],['지점',/지점/]].filter(([,pattern])=>pattern.test(value));return matches.length===1?matches[0][0]:'자동';}
function parseAiBulk(raw){
 const rows=parseAiGrid(raw);if(!rows.length)return {items:[],errors:[],skipped:[]};
 let headerIndex=rows.findIndex(row=>Object.keys(aiHeaderMap(row)).length>=2),headers=headerIndex>=0?aiHeaderMap(rows[headerIndex]):null,start=headerIndex>=0?headerIndex+1:0;
 const items=[],errors=[],skipped=[],seen=new Set(),cell=(row,name)=>headers&&headers[name]!==undefined?String(row[headers[name]]||'').trim():'';
 rows.slice(start).forEach((row,offset)=>{
  const line=start+offset+1;
  if(!headers){const topic=String(row[0]||'').trim(),category=String(row[1]||'자동').trim()||'자동';if(!topic)return;row={topic,category};}
  const progress=headers?cell(row,'progress'):'',brief=headers?cell(row,'brief'):'',keywords=headers?cell(row,'keywords'):'',material=brief.match(/\[소재\]\s*([^\r\n]+)/i);
  const topic=headers?String(cell(row,'topic')||material?.[1]||brief.split(/\r?\n/).find(value=>value.trim())||keywords).replace(/^[\-ㄴ]\s*/,'').trim():row.topic;
  const category=headers?(cell(row,'category')||inferAiCategory(`${keywords}\n${brief}`)):row.category;
  if(/발행|게시\s*완료/.test(progress)){skipped.push({line,reason:'이미 발행됨',topic:topic||keywords||`${line}행`});return;}
  if(!topic){if(row.some(value=>String(value||'').trim()))errors.push(`${line}행: [소재] 문장이나 주제를 찾지 못했습니다.`);return;}
  if(topic.length>200){errors.push(`${line}행: 주제는 200자 이내로 입력해 주세요.`);return;}
  if(!AI_ALLOWED_CATEGORIES.includes(category)){errors.push(`${line}행: 카테고리는 자동·상호·본점·목적·임원·지점 중에서 입력해 주세요.`);return;}
  const key=topic.toLowerCase();if(seen.has(key)){errors.push(`${line}행: 같은 주제가 붙여넣기 안에 중복되어 있습니다.`);return;}seen.add(key);
  items.push({topic,category,brief,planning:headers?{sequence:cell(row,'sequence'),month:cell(row,'month'),progress,assignee:cell(row,'assignee'),publishDate:cell(row,'publishDate'),weekday:cell(row,'weekday'),series:cell(row,'series'),keywords,blogUrl:cell(row,'blogUrl'),references:cell(row,'references')}:{}});
 });
 if(items.length>50)errors.push('한 번에 최대 50건까지 생성할 수 있습니다.');
 return {items,errors,skipped};
}
function updateAiBulkPreview(){const parsed=parseAiBulk($('aiBulkInput').value),box=$('aiBulkValidation'),preview=$('aiBulkPreview');const remaining=aiStatus?Math.max(0,aiStatus.dailyLimit-aiStatus.usedToday):null;box.className='ai-bulk-validation '+(parsed.errors.length?'error':parsed.items.length?'ok':'');box.textContent=parsed.errors[0]||`${parsed.items.length}건 생성 · ${parsed.skipped.length}건 제외${remaining===null?'':` · 오늘 남은 한도 ${remaining}건`}`;preview.hidden=!parsed.items.length;preview.innerHTML=parsed.items.slice(0,8).map((item,index)=>`<span><b>${index+1}</b>${aiEscape(item.topic)}<small>${aiEscape([item.category,item.planning?.series,item.planning?.publishDate].filter(Boolean).join(' · '))}</small></span>`).join('')+(parsed.items.length>8?`<em>외 ${parsed.items.length-8}건</em>`:'');return parsed;}
