async function refreshAiDashboard(){try{const {items}=await aiApi('list');items.forEach(job=>aiJobs.set(job.id,job));renderAiDashboard();}catch(e){if(!/로그인/.test(e.message))console.warn('AI dashboard refresh failed');}}
function enqueueAiJob(job){aiJobs.set(job.id,job);if(!aiQueue.includes(job.id)&&!['done','failed'].includes(job.status))aiQueue.push(job.id);renderAiDashboard();runAiQueue();}
async function runAiQueue(){if(aiWorkerRunning)return;aiWorkerRunning=true;while(aiQueue.length){const id=aiQueue.shift();let job=aiJobs.get(id),failures=0;if(!job||['done','failed'].includes(job.status))continue;aiFocusedId=id;focusAiJob(job);while(!['done','failed'].includes(job.status)){try{({job}=await aiApi('advance',{method:'POST',body:{id}}));failures=0;aiJobs.set(id,job);focusAiJob(job);renderAiDashboard();if(!['done','failed'].includes(job.status))await aiSleep(job.steps.some(step=>step.status==='running')?1500:250);}catch(error){if(++failures>=3){aiProgressMessage(error.message,'error');break;}await aiSleep(1500);}}updateAiBatchProgress();}aiWorkerRunning=false;renderAiDashboard();if(aiBatchIds.length>1){const jobs=aiBatchIds.map(id=>aiJobs.get(id)).filter(Boolean);if(jobs.length===aiBatchIds.length&&jobs.every(job=>['done','failed'].includes(job.status))){const failed=jobs.filter(job=>job.status==='failed').length;$('aiProgTitle').textContent=failed?'일괄 생성이 일부 완료됐어요':'일괄 생성 완료';$('aiProgSub').textContent=`완료 ${jobs.length-failed}건 · 실패 ${failed}건`;$('aiProgOpen').hidden=false;aiProgressMessage(failed?'실패한 작업은 대시보드에서 다시 시도할 수 있어요.':'모든 글이 작성 중 · 검토 전으로 저장됐어요.',failed?'error':'ok');}}refreshAiDashboard();}
$('aiLiveRefresh').onclick=refreshAiDashboard;
$('aiLiveJobs').onclick=async event=>{const button=event.target.closest('[data-ai-job-action]');if(!button)return;const job=aiJobs.get(button.dataset.jobId);if(!job)return;if(job.status==='done'){$('navContents').click();$('refresh').click();return;}if(job.status==='failed'){try{const {job:retried}=await aiApi('retry',{method:'POST',body:{id:job.id}});aiJobs.set(job.id,retried);enqueueAiJob(retried);focusAiJob(retried);openDialog($('aiProgressDialog'));}catch(error){toast(error.message);}return;}focusAiJob(job);openDialog($('aiProgressDialog'));enqueueAiJob(job);};
$('aiProgRetry').onclick=async()=>{const id=$('aiProgRetry').dataset.job;if(!id)return;try{const {job}=await aiApi('retry',{method:'POST',body:{id}});focusAiJob(job);enqueueAiJob(job);}catch(e){aiProgressMessage(e.message,'error');}};
