$('aiGenerationForm').onsubmit=async event=>{
 event.preventDefault();const form=event.currentTarget;if(!form.querySelector('input[name="channel"][value="home"]').checked){toast('지금은 홈페이지 글만 만들 수 있어요.');return;}let requests=[];
 const contentType=$('aiContentType').value;if(aiGenerationMode==='bulk'){const parsed=updateAiBulkPreview();if(parsed.errors.length){toast(parsed.errors[0]);$('aiBulkInput').focus();return;}if(!parsed.items.length){toast(parsed.skipped.length?'생성할 행이 없습니다. 이미 발행된 행을 제외했는지 확인해 주세요.':'엑셀에서 제목 행과 생성할 행을 복사해 붙여넣어 주세요.');$('aiBulkInput').focus();return;}if(aiStatus&&parsed.items.length>aiStatus.dailyLimit-aiStatus.usedToday){toast(`오늘 남은 생성 한도는 ${Math.max(0,aiStatus.dailyLimit-aiStatus.usedToday)}건입니다.`);return;}requests=parsed.items.map(item=>({topic:item.topic,category:AI_CATEGORY_MAP[item.category]||'',contentType,brief:item.brief,planning:item.planning}));}else{const data=new FormData(form),manual=data.get('topicMode')==='manual',topic=manual?$('aiTopicInput').value.trim():'';if(manual&&!topic){toast('직접 작성할 주제를 입력해 주세요.');$('aiTopicInput').focus();return;}if(topic.length>200){toast('주제는 200자 이내로 입력해 주세요.');return;}requests=[{topic,category:AI_CATEGORY_MAP[$('aiCategory').value]||'',contentType}];}
 const submit=form.querySelector('button[type="submit"]');submit.disabled=true;submit.textContent='작업 등록 중…';const created=[];try{for(let index=0;index<requests.length;index++){submit.textContent=`작업 등록 ${index+1}/${requests.length}`;const {job}=await aiApi('create',{method:'POST',body:requests[index]});created.push(job);aiJobs.set(job.id,job);}if(!created.length)return;aiBatchIds=created.map(job=>job.id);$('aiGenerationDialog').close();focusAiJob(created[0]);openDialog($('aiProgressDialog'));created.forEach(enqueueAiJob);refreshAiDashboard();}catch(error){toast(created.length?`${created.length}건은 등록했고, 나머지는 실패했어요: ${error.message}`:error.message);if(created.length){aiBatchIds=created.map(job=>job.id);$('aiGenerationDialog').close();focusAiJob(created[0]);openDialog($('aiProgressDialog'));created.forEach(enqueueAiJob);}}finally{submit.disabled=false;submit.textContent='생성 요청';}
};
