function appendText(parent,tag,text,className=''){const node=document.createElement(tag);node.textContent=text;if(className)node.className=className;parent.append(node);return node;}
function renderHomeqDraft(item){if(!item?.draft)return;const draft=item.draft;$('homeqDraftPanel').hidden=false;$('homeqDraftTitle').textContent=`${item.targetWeek} 부동산 주간뉴스 초안`;$('homeqDraftMeta').textContent=`${new Date(item.updatedAt).toLocaleString('ko-KR')} 생성 · ${item.ruleVersion} · ${item.model}`;$('homeqDraftStatus').textContent=item.status==='topic_review'?'주제 검토 필요':'원고 검토 전';
 const cover=$('homeqCoverDraft');cover.replaceChildren();appendText(cover,'span','표지 문구');appendText(cover,'strong',`${draft.cover.titleLine1} ${draft.cover.titleLine2}`);appendText(cover,'p',draft.cover.subtitle);const coverPrompt=document.createElement('details');const coverSummary=appendText(coverPrompt,'summary','표지 이미지 프롬프트');appendText(coverPrompt,'p',draft.cover.imagePrompt);cover.append(coverPrompt);coverSummary.setAttribute('role','button');
 const topics=$('homeqDraftTopics');topics.replaceChildren();draft.topics.forEach(topic=>{const article=document.createElement('article');const head=document.createElement('div');appendText(head,'span',`${topic.order}꼭지 · ${topic.category}`);appendText(head,'h3',`${topic.titleLine1} ${topic.titleLine2}`);article.append(head);appendText(article,'strong',topic.keySentence,'homeq-key-sentence');const list=document.createElement('ul');topic.bodyLines.forEach(line=>appendText(list,'li',line));article.append(list);const source=document.createElement('a');source.href=topic.sourceUrl;source.target='_blank';source.rel='noopener noreferrer';source.textContent=`출처: ${topic.sourceName} · ${topic.sourceDate}`;article.append(source);const imageDetails=document.createElement('details');appendText(imageDetails,'summary','이미지 프롬프트');appendText(imageDetails,'p',topic.imagePrompt);article.append(imageDetails);topics.append(article);});
 $('homeqDraftCaption').textContent=draft.instagramCaption+'\n\n'+draft.hashtags.join(' ');const notes=$('homeqReviewNotes');notes.replaceChildren();if(draft.reviewNotes?.length){appendText(notes,'strong','업로드 전 확인');const list=document.createElement('ul');draft.reviewNotes.forEach(note=>appendText(list,'li',note));notes.append(list);notes.hidden=false;}else notes.hidden=true;homeqDraftWeek=item.targetWeek;
}
